      case parse_rule__value(stream, pos, ref_stack, context) do
        {:ok, new_pos, new_ref_stack, sub_captures} ->
          {:ok, new_pos, new_ref_stack, %{arg: {:rule, :value, sub_captures}}}

        _fail ->
          :fail
      end
    end

    def parse_expr__423(stream, pos, ref_stack, _context) do
      case Parser.match_token(stream, pos, :TRIVIA) do
        {:ok, new_pos, _text, _capture} -> {:ok, new_pos, ref_stack, %{}}
        :fail -> :fail
      end
    end

    def parse_expr__422(stream, pos, ref_stack, context) do
      Parser.star(&parse_expr__423/4, stream, pos, ref_stack, context)
    end

    def parse_expr__424(stream, pos, ref_stack, _context) do
      case Parser.match_token(stream, pos, :ANON_18) do
        {:ok, new_pos, _text, _capture} -> {:ok, new_pos, ref_stack, %{}}
        :fail -> :fail
      end
    end

    def parse_rule__tagged_ref(stream, pos, ref_stack, context) do
      with {:ok, pos1, ref1, cap0} <- parse_expr__412(stream, pos, ref_stack, context),
           {:ok, pos2, ref2, cap1} <- parse_expr__413(stream, pos1, ref1, context),
           {:ok, pos3, ref3, cap2} <- parse_expr__415(stream, pos2, ref2, context),
           {:ok, pos4, ref4, cap3} <- parse_expr__416(stream, pos3, ref3, context),
           {:ok, pos5, ref5, cap4} <- parse_expr__418(stream, pos4, ref4, context),
           {:ok, pos6, ref6, cap5} <- parse_expr__419(stream, pos5, ref5, context),
           {:ok, pos7, ref7, cap6} <- parse_expr__421(stream, pos6, ref6, context),
           {:ok, pos8, ref8, cap7} <- parse_expr__422(stream, pos7, ref7, context),
           {:ok, pos9, ref9, cap8} <- parse_expr__424(stream, pos8, ref8, context) do
        {:ok, pos9, ref9,
         Parser.merge_captures(
           cap0,
           Parser.merge_captures(
             cap1,
             Parser.merge_captures(
               cap2,
               Parser.merge_captures(
                 cap3,
                 Parser.merge_captures(
                   cap4,
                   Parser.merge_captures(
                     cap5,
                     Parser.merge_captures(cap6, Parser.merge_captures(cap7, cap8))
                   )
                 )
               )
             )
           )
         )}
      else
        _fail -> :fail
      end
    end

    (
      @doc "Tokenizes `input` completely via maximal munch, applies any `@keywords`/`@refine` rules, or reports the first position nothing matches. `context` is read-only and only ever consulted by a `Grammar.IR.CustomLexeme` `@native(...)` token, if the grammar has one."
      @spec tokenize(String.t(), term()) :: {:ok, [Token.t()]} | {:error, Ichor.Error.t()}
      def tokenize(input, context \\ nil) do
        with {:ok, input} <- Grammar.Source.validate(input),
             {:ok, raw_tokens} <-
               Tokenizer.tokenize(fn inp -> lex_candidates(inp, context) end, input) do
          Grammar.Lexer.reclassify(raw_tokens, %{})
        end
      end
    )

    @doc "Matches `input` against the grammar's root rule, requiring the entire (tokenized) input to be consumed. A bare recognizer -- no `Ichor.Actions` involved. `context` is read-only and only ever consulted by a `Grammar.IR.Custom` `@native(...)` node, if the grammar has one."
    @spec parse(String.t(), term()) :: {:ok, non_neg_integer(), map()} | {:error, Ichor.Error.t()}
    def parse(input, context \\ nil) do
      with {:ok, tokens} <- tokenize(input, context) do
        stream = List.to_tuple(tokens)

        case parse_rule__file(stream, 0, [0], context) do
          {:ok, pos, _ref_stack, raw_captures} when pos == tuple_size(stream) ->
            {:ok, pos, raw_captures}

          {:ok, pos, _ref_stack, _raw_captures} ->
            {:error, Parser.unexpected_token_error(stream, pos, input)}

          _fail ->
            {:error,
             Ichor.Error.new(
               message: "input does not match #{inspect(:file)}",
               stage: :parser,
               source: input
             )}
        end
      end
    end

    @doc "Like `parse/1`, but runs the match through the compile-time-known Actions module, returning the grammar's actual evaluated result."
    @spec run(String.t(), Ichor.Actions.context()) ::
            {:ok, term()} | {:error, Ichor.Error.t() | [Ichor.Error.t()]}
    def run(input, initial_context \\ nil) do
      with {:ok, _pos, raw_captures} <- parse(input, initial_context),
           {:ok, value, _context} <-
             Ichor.Actions.evaluate(:file, raw_captures, Cooper.Actions, initial_context, %{
               ref_suffix: MapSet.new([]),
               key_segment: MapSet.new([]),
               version_number: MapSet.new([:n]),
               version_head: MapSet.new([]),
               var_decl: MapSet.new([]),
               idx_suffix: MapSet.new([]),
               tuple: MapSet.new([:value]),
               statement: MapSet.new([]),
               env_guard: MapSet.new([]),
               version_header: MapSet.new([]),
               resolver_ref: MapSet.new([]),
               value: MapSet.new([]),
               list: MapSet.new([:value]),
               env_ref: MapSet.new([]),
               atom_value: MapSet.new([]),
               binding: MapSet.new([]),
               seg: MapSet.new([]),
               import_path: MapSet.new([]),
               atom_word: MapSet.new([]),
               conditional_statement: MapSet.new([]),
               sigil_kv_statement: MapSet.new([]),
               key_path: MapSet.new([:key_segment]),
               disabled_statement: MapSet.new([]),
               at_ref: MapSet.new([]),
               block: MapSet.new([:statement]),
               import_statement: MapSet.new([]),
               iterable_value: MapSet.new([]),
               config_ref: MapSet.new([]),
               rhs: MapSet.new([]),
               env_bracket: MapSet.new([]),
               delete_statement: MapSet.new([]),
               colon_atom: MapSet.new([]),
               for_statement: MapSet.new([:binding]),
               file: MapSet.new([:statement]),
               real_statement: MapSet.new([]),
               tagged_ref: MapSet.new([])
             }) do
        {:ok, value}
      end
    end

    @doc "Like `run/2`, but evaluates `input` as a sequence of top-level matches against the root rule, one after another, threading context from each into the next (loading a standard-library file one top-level form at a time is the motivating case -- most grammars only ever need `run/2`)."
    @spec run_sequence(String.t(), Ichor.Actions.context()) ::
            {:ok, [term()], Ichor.Actions.context()}
            | {:error, Ichor.Error.t() | [Ichor.Error.t()]}
    def run_sequence(input, initial_context) do
      with {:ok, tokens} <- tokenize(input, initial_context) do
        do_run_sequence(List.to_tuple(tokens), 0, initial_context, [])
      end
    end

    def do_run_sequence(stream, pos, ctx, acc) do
      pos = Parser.skip_leading_trivia(stream, pos, :TRIVIA)

      if pos >= tuple_size(stream) do
        {:ok, Enum.reverse(acc), ctx}
      else
        case parse_rule__file(stream, pos, [0], ctx) do
          {:ok, new_pos, _ref_stack, raw_captures} ->
            case Ichor.Actions.evaluate(:file, raw_captures, Cooper.Actions, ctx, %{
                   ref_suffix: MapSet.new([]),
                   key_segment: MapSet.new([]),
                   version_number: MapSet.new([:n]),
                   version_head: MapSet.new([]),
                   var_decl: MapSet.new([]),
                   idx_suffix: MapSet.new([]),
                   tuple: MapSet.new([:value]),
                   statement: MapSet.new([]),
                   env_guard: MapSet.new([]),
                   version_header: MapSet.new([]),
                   resolver_ref: MapSet.new([]),
                   value: MapSet.new([]),
                   list: MapSet.new([:value]),
                   env_ref: MapSet.new([]),
                   atom_value: MapSet.new([]),
                   binding: MapSet.new([]),
                   seg: MapSet.new([]),
                   import_path: MapSet.new([]),
                   atom_word: MapSet.new([]),
                   conditional_statement: MapSet.new([]),
                   sigil_kv_statement: MapSet.new([]),
                   key_path: MapSet.new([:key_segment]),
                   disabled_statement: MapSet.new([]),
                   at_ref: MapSet.new([]),
                   block: MapSet.new([:statement]),
                   import_statement: MapSet.new([]),
                   iterable_value: MapSet.new([]),
                   config_ref: MapSet.new([]),
                   rhs: MapSet.new([]),
                   env_bracket: MapSet.new([]),
                   delete_statement: MapSet.new([]),
                   colon_atom: MapSet.new([]),
                   for_statement: MapSet.new([:binding]),
                   file: MapSet.new([:statement]),
                   real_statement: MapSet.new([]),
                   tagged_ref: MapSet.new([])
                 }) do
              {:ok, value, new_ctx} -> do_run_sequence(stream, new_pos, new_ctx, [value | acc])
              {:error, _} = err -> err
            end

          _fail ->
            {:error,
             Ichor.Error.new(message: "input does not match #{inspect(:file)}", stage: :parser)}
        end
      end
    end
  )
end
